"""Pydantic schemas for the A2A eval pipeline.

Defines structured types for tasks, judgments, and executive decisions
used by the Planner, Coder, and Judge throughout the experiment.
"""

from __future__ import annotations

from typing import Literal, Optional

from pydantic import BaseModel, Field


# ---------------------------------------------------------------------------
# Task schema — generated by the Planner
# ---------------------------------------------------------------------------

AmbiguityLevel = Literal["low", "medium", "high"]
TaskCategory = Literal[
    "data_transformation",
    "business_logic",
    "string_text_processing",
    "algorithmic",
    "api_interface_design",
]
ComplexityAxis = Literal[
    "edge_case_heavy",
    "implicit_constraints",
    "multi_step",
    "domain_specific_terms",
    "ambiguous_boundary",
    "underspecified_error_handling",
    "ordering_ambiguity",
]


class A2ATask(BaseModel):
    """A single task generated by the Planner for delegation to the Coder.

    The ``description`` is the ONLY thing the Coder sees.
    The ``intent_summary`` is private to the Planner and used for
    judgment anchoring.
    """

    task_id: str = Field(..., description="Unique ID, e.g. 'A2A/001'")
    description: str = Field(
        ...,
        description=(
            "Natural language task description — this is what the Coder "
            "receives. Should be realistic but contain implicit constraints "
            "or ambiguities that could cause intent drift."
        ),
    )
    function_name: str = Field(
        ...,
        description="The exact function name the Coder must implement.",
    )
    intent_summary: str = Field(
        ...,
        description=(
            "Planner's private summary of what it actually wants. "
            "Includes implicit constraints, edge-case expectations, and "
            "specific behaviors that are NOT fully spelled out in the "
            "description. Never shown to the Coder."
        ),
    )
    category: TaskCategory = Field(
        ..., description="Which of the 5 task categories this belongs to."
    )
    complexity_axes: list[ComplexityAxis] = Field(
        default_factory=list,
        description="Which complexity axes apply to this task.",
    )
    ambiguity_level: AmbiguityLevel = Field(
        ..., description="How ambiguous is the description? low/medium/high."
    )


class A2ATaskBank(BaseModel):
    """Container for the full bank of generated tasks."""

    tasks: list[A2ATask] = Field(default_factory=list)


# ---------------------------------------------------------------------------
# Executive decision (Planner reviewing CNL in DYTM condition)
# ---------------------------------------------------------------------------

class A2AExecutiveDecision(BaseModel):
    """Structured output from the Planner-as-Executive CNL review."""

    approved: bool = Field(..., description="Whether the contract is approved.")
    feedback: str = Field(
        default="",
        description="If rejected, what specifically is missing or wrong.",
    )


# ---------------------------------------------------------------------------
# Judgment schema — Planner evaluating final Coder output
# ---------------------------------------------------------------------------

DriftCategory = Literal[
    "boundary_condition",
    "implicit_constraint",
    "domain_term",
    "edge_case",
    "return_type",
    "error_handling",
    "ordering",
    "performance",
    "none",
    "other",
]


class A2AJudgment(BaseModel):
    """Structured output from the Planner judging the Coder's final code."""

    intent_match: int = Field(
        ...,
        ge=1,
        le=5,
        description=(
            "1-5 scale: does the code do what the Planner meant? "
            "5=perfect, 4=minor miss, 3=significant miss on one axis, "
            "2=fundamentally misunderstood, 1=completely wrong."
        ),
    )
    drift_detected: bool = Field(
        ...,
        description="Is there any gap between Planner intent and Coder output?",
    )
    drift_description: str = Field(
        default="",
        description="What specifically was misunderstood (if drift detected).",
    )
    drift_category: DriftCategory = Field(
        default="none",
        description="Category of drift, or 'none' if no drift.",
    )


# ---------------------------------------------------------------------------
# Baseline feedback (Planner giving NL feedback to Coder)
# ---------------------------------------------------------------------------

class A2ABaselineFeedback(BaseModel):
    """Structured output from the Planner reviewing Coder output mid-loop."""

    satisfied: bool = Field(
        ..., description="Does the code match the Planner's intent?"
    )
    feedback: str = Field(
        default="",
        description="If not satisfied, NL feedback for the Coder to retry.",
    )


# ---------------------------------------------------------------------------
# Result records (for CSV logging)
# ---------------------------------------------------------------------------

class A2AResult(BaseModel):
    """Single-task result for either condition."""

    task_id: str
    condition: Literal["baseline", "dytm"]
    planner_model: str
    coder_model: str

    # Outcome
    final_intent_match: int = Field(..., ge=1, le=5)
    drift_detected: bool
    drift_category: DriftCategory = "none"
    drift_description: str = ""

    # Communication metrics
    rounds_to_agreement: int = Field(
        ..., description="Total interaction rounds before Planner accepted."
    )
    first_attempt_aligned: bool = Field(
        ..., description="Did the first attempt match Planner intent?"
    )

    # DYTM-specific
    contract_rejections: int = Field(
        default=0,
        description="(DYTM only) How many times the Planner rejected the CNL.",
    )
    pbt_retries: int = Field(
        default=0,
        description="(DYTM only) How many PBT-driven code retries occurred.",
    )
    contract_faithfulness: Optional[int] = Field(
        default=None,
        description="(DYTM only) Planner rating of the approved CNL (1-5).",
    )

    # Cost
    total_llm_calls: int = 0
    wall_clock_sec: float = 0.0

    # Judgment reliability
    judgment_votes: list[int] = Field(
        default_factory=list,
        description="3x judgment intent_match votes for majority calculation.",
    )

